WITH kept AS (SELECT s.* FROM suppliers s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.category IN ('Electronics', 'Fashion'))) SELECT CASE WHEN rating >= 4.5 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, city, STDDEV_SAMP(rating) AS rating_stddev, PERCENTILE_APPROX(rating, 0.5) AS rating_p50, MAX(rating) FILTER (WHERE city = 'Tokyo') AS tokyo_max_rating, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) AS tokyo_count, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, COUNT(DISTINCT country) AS distinct_countries FROM kept GROUP BY 1, 2 HAVING de_count < 1 ORDER BY rating_p50 DESC NULLS LAST
